/// <summary>
/// The data contract class for the batch job
/// </summary>
[DataContractAttribute]
class METAutoSettleCustomerTransactionsContract
{
    private str packedQuery;

}

Method.Source:
/// <summary>
/// Gets or sets the packed query used to retrieve customer transactions for auto-settlement.
/// This query is defined by the METCustTransAutoSettelement query object and is passed through the batch job contract.
/// </summary>
/// <param name="_packedQuery">The base64-encoded query string to be stored or retrieved.</param>
/// <returns>The packed query string.</returns>
[DataMemberAttribute,
AifQueryTypeAttribute('_packedQuery', queryStr(METCustTransAutoSettelement)),
SysOperationLabelAttribute("@MET:AutoSettleCustTrans")]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Decodes the packed query string and returns a Query object.
/// This method is used to reconstruct the original query passed through the contract,
/// enabling execution of the query within the service logic.
/// </summary>
/// <returns>The decoded Query object.</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}
